action.code:
unique_songs = set()

# Add library songs
if 'items' in library_songs:
    for item in library_songs['items']:
        if 'track' in item and 'id' in item['track']:
            unique_songs.add(item['track']['id'])

# Add songs from albums
if 'items' in albums:
    for album in albums['items']:
        album_songs = apis.Spotify.get_album_songs(album_id=album['id'], access_token=access_token)
        if 'items' in album_songs:
            for song in album_songs['items']:
                if 'id' in song:
                    unique_songs.add(song['id'])

# Add songs from playlists
if 'items' in playlists:
    for playlist in playlists['items']:
        playlist_songs = apis.Spotify.get_playlist_songs(playlist_id=playlist['id'], access_token=access_token)
        if 'items' in playlist_songs:
            for item in playlist_songs['items']:
                if 'track' in item and 'id' in item['track']:
                    unique_songs.add(item['track']['id'])

print(f"Total unique songs: {len(unique_songs)}")

