# Let's look at all transactions from yesterday (2023-05-17)
yesterday_transactions = []
if 'data' in feed:
    for txn in feed['data']:
        # Check if transaction is from yesterday
        if '2023-05-17' in txn.get('date', ''):
            yesterday_transactions.append(txn)

print(f"Transactions from yesterday (2023-05-17):")
for txn in yesterday_transactions:
    print(f"  {txn.get('description')} - ${txn.get('amount')} from {txn.get('from')} to {txn.get('to')}")

