# Collect all unique song IDs
unique_song_ids = set()

# Add song IDs from liked songs
for song in liked_songs:
    unique_song_ids.add(song['song_id'])

print(f"Unique songs from liked songs: {len(unique_song_ids)}")

# Add song IDs from liked albums
for album in liked_albums:
    for song_id in album['song_ids']:
        unique_song_ids.add(song_id)

print(f"Unique songs after adding albums: {len(unique_song_ids)}")

# Add song IDs from all playlists
for playlist in playlists:
    for song_id in playlist['song_ids']:
        unique_song_ids.add(song_id)

print(f"Total unique songs across all sources: {len(unique_song_ids)}")

