# Filter transactions from yesterday that mention Azure Harbor or are payments to manager
yesterday_transactions = []
for tx in transactions_response.get('transactions', []):
    tx_date = tx.get('date', '')
    # Check if transaction is from 2023-05-17
    if '2023-05-17' in tx_date:
        yesterday_transactions.append(tx)

print(f"Found {len(yesterday_transactions)} transactions from yesterday:")
for tx in yesterday_transactions:
    print(f"  Amount: ${tx.get('amount')}, Note: {tx.get('note')}, From: {tx.get('from')}, To: {tx.get('to')}")

# Let's print all transactions from yesterday to see the full structure
yesterday = datetime.date(2023, 5, 17)
all_yesterday = []

for tx in transactions:
    tx_date_str = tx.get('date', '')
    if tx_date_str:
        try:
            tx_date = datetime.datetime.fromisoformat(tx_date_str).date()
            if tx_date == yesterday:
                all_yesterday.append(tx)
        except:
            pass

print(f"All transactions from yesterday ({yesterday}):")
for tx in all_yesterday:
    print(f"From: {tx.get('from_user')}, To: {tx.get('to_user')}, Amount: {tx.get('amount')}, Note: {tx.get('note')}")

