# Get creation dates for all files
file_metadata = {}
for file_path in files_list:
    file_info = apis.file_system.show_file(file_path=file_path, access_token=access_token)
    file_metadata[file_path] = {
        'created_at': file_info['created_at'],
        'updated_at': file_info['updated_at']
    }

# Print a few examples
for i, (path, meta) in enumerate(list(file_metadata.items())[:5]):
    print(f"{path}: created {meta['created_at']}")

