action.code:
# Get file details for all files to extract creation dates
from datetime import datetime

files_data = []
for file_path in result:
    file_info = apis.file_system.show_file(access_token=token, file_path=file_path)
    files_data.append({
        'path': file_path,
        'created_at': file_info['created_at'],
        'filename': file_path.split('/')[-1]
    })

# Display first few files with their creation dates
for f in files_data[:5]:
    print(f"{f['filename']} - Created: {f['created_at']}")

